// Ouverture du lien de désinscription : on demande un clic sur un bouton, pour que les antivirus de messagerie
// (qui ouvrent les liens tout seuls) ne désinscrivent personne par erreur.
const page = (titre, texte, extra = '') => `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${titre}</title></head>
<body style="margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#f7f8f5;font-family:Arial,Helvetica,sans-serif;color:#0f1a14">
<main style="max-width:440px;margin:24px;padding:32px 28px;background:#ffffff;border:1px solid #dfe4dc;border-radius:20px;text-align:center">
<div style="font-size:12px;letter-spacing:1px;text-transform:uppercase;color:#146c43;font-weight:bold">Baromètre mangue</div>
<h1 style="font-size:22px;margin:12px 0">${titre}</h1><p style="font-size:15px;line-height:1.6;color:#3d4a42">${texte}</p>${extra}
</main></body></html>`;
const j = String($json.query?.j ?? '').replace(/[^a-zA-Z0-9-]/g, '');
const bouton = `<form method="post" action="?j=${j}" style="margin-top:24px"><input type="hidden" name="j" value="${j}">
<button type="submit" style="background:#c2410c;color:#ffffff;border:0;font-size:15px;font-weight:bold;padding:14px 28px;border-radius:999px;cursor:pointer">Me désinscrire</button></form>`;
return [{ json: { html: j ? page('Se désinscrire ?', 'Vous ne recevrez plus le bulletin gratuit du vendredi.', bouton) : page('Lien invalide', 'Ce lien est incomplet.') } }];

parameters.query:
with m as (
  update ie.prospects set statut = 'desinscrit', desinscrit_le = now(), maj_le = now()
  where jeton = $1 and statut <> 'desinscrit'
  returning statut
)
select coalesce((select statut from m), (select statut from ie.prospects where jeton = $1), 'inconnu') as statut;

