// Page affichée après le clic sur « Me désinscrire ».
const page = (titre, texte, extra = '') => `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${titre}</title></head>
<body style="margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#f7f8f5;font-family:Arial,Helvetica,sans-serif;color:#0f1a14">
<main style="max-width:440px;margin:24px;padding:32px 28px;background:#ffffff;border:1px solid #dfe4dc;border-radius:20px;text-align:center">
<div style="font-size:12px;letter-spacing:1px;text-transform:uppercase;color:#146c43;font-weight:bold">Baromètre mangue</div>
<h1 style="font-size:22px;margin:12px 0">${titre}</h1><p style="font-size:15px;line-height:1.6;color:#3d4a42">${texte}</p>${extra}
</main></body></html>`;
const statut = $input.first()?.json?.statut ?? 'erreur';
const [titre, texte] = statut === 'desinscrit'
  ? ['Vous êtes désinscrit', 'C\'est fait : vous ne recevrez plus le bulletin. Vous pouvez vous réinscrire à tout moment depuis le site.']
  : statut === 'inconnu'
    ? ['Lien invalide', 'Ce lien est incomplet ou a expiré.']
    : ['Un souci technique', 'La désinscription n\'a pas pu être enregistrée. Répondez simplement à un de nos e-mails : nous le ferons à la main.'];
return [{ json: { html: page(titre, texte) } }];

// RÉGLAGES : mêmes valeurs que dans le nœud « Réglages » du workflow 02.
const EXPEDITEUR = 'Baromètre IE <onboarding@resend.dev>';
const ADMIN = 'a-remplacer@exemple.com'; // votre e-mail : reçoit la liste des nouveaux membres

// Un seul e-mail pour vous, avec les membres confirmés depuis le dernier passage.
const PROFILS = { exportateur: 'Exportateur', cooperative: 'Coopérative', acheteur: 'Acheteur / importateur', institution: 'Institution', autre: 'Autre' };
const gens = $input.all().map((i) => i.json).filter((p) => p.email);
if (!gens.length) return [];
return [{ json: { chemin: 'emails', corps: {
  from: EXPEDITEUR,
  to: [ADMIN],
  subject: `[Espace membre] ${gens.length} nouveau(x) membre(s)`,
  text: gens.map((p) => `• ${p.email} · ${PROFILS[p.profil] ?? 'profil non précisé'} · source ${p.source} · ${p.quand}`).join('\n')
    + '\n\nIls reçoivent le bulletin gratuit du vendredi. Pour en passer un en Premium : Supabase → Table Editor → ie → abonnes → Insert row'
    + ' (email, formule, date_fin), puis sa ligne prospects en statut « client ».',
} } }];
